// GENERATED by catching.py — disposable, never committed.
using MessagePack.SourceGenerator.Tests;
using MessagePack.SourceGenerator;
using MessagePack;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using Microsoft.CodeAnalysis;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Threading;
using System;
using Xunit;
public class CatchingTests
{
    private const string RichSource = @"
using System;
using MessagePack;
namespace App
{
    [MessagePackObject] public class Person { [Key(0)] public string Name { get; set; } [Key(1)] public int Age { get; set; } }
    [MessagePackObject(true)] public class Named { public string Title { get; set; } public int N { get; set; } }
    public enum Color { Red, Green }
    [MessagePackObject] public class Painted { [Key(0)] public Color C { get; set; } }
    [Union(0, typeof(Dog))] [Union(1, typeof(Cat))] public interface IAnimal { }
    [MessagePackObject] public class Dog : IAnimal { [Key(0)] public string Name { get; set; } }
    [MessagePackObject] public class Cat : IAnimal { [Key(0)] public string Name { get; set; } }
    [MessagePackObject] public class Box<T> { [Key(0)] public T Value { get; set; } }
    [GeneratedMessagePackResolver] public partial class MyResolver { public int UserMember => 42; }
}";

    private static readonly string[][] AttributeTargets =
    {
        new string[0],
        new[] { "NET8_0", "NET8_0_OR_GREATER" },
        new[] { "NET6_0", "NET6_0_OR_GREATER" },
        new[] { "NETCOREAPP3_1" },
        new[] { "NETSTANDARD2_1" },
    };

    private static readonly string[][] LegacyTargets =
    {
        new[] { "NETSTANDARD2_0" },
        new[] { "NETFRAMEWORK", "NET472" },
        new[] { "NETSTANDARD2_0", "NETFRAMEWORK" },
    };

    private static async Task<(Compilation Output, ImmutableArray<Diagnostic> Diags)> RunAsync(string source)
    {
        ImmutableArray<MetadataReference> refs = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create("Catching",
            [CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest))],
            refs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outputCompilation, out _);
        return (outputCompilation, outputCompilation.GetDiagnostics());
    }

    private static Compilation Reparse(Compilation output, string[] symbols)
    {
        var opts = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: symbols);
        var trees = output.SyntaxTrees
            .Select(t => CSharpSyntaxTree.ParseText(t.GetText(), opts, t.FilePath))
            .ToArray();
        return output.RemoveAllSyntaxTrees().AddSyntaxTrees(trees);
    }

    private static List<Diagnostic> CompilerErrors(Compilation c) =>
        c.GetDiagnostics()
            .Where(d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("CS", StringComparison.Ordinal))
            .ToList();

    private static string Describe(IEnumerable<Diagnostic> d) => string.Join(Environment.NewLine, d.Select(x => x.ToString()));

    private static bool HasCoverageAttr(INamedTypeSymbol s) =>
        s.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute"
            && a.AttributeClass.ContainingNamespace.ToDisplayString() == "System.Diagnostics.CodeAnalysis");

    // Types emitted by the generator (excludes user-declared types, except user partial resolvers which the generator extends).
    private static List<INamedTypeSymbol> EmittedTypes(Compilation comp)
    {
        SyntaxTree original = comp.SyntaxTrees.First();
        SemanticModel om = comp.GetSemanticModel(original);
        var userTypes = new HashSet<string>(
            original.GetRoot().DescendantNodes().OfType<BaseTypeDeclarationSyntax>()
                .Select(d => om.GetDeclaredSymbol(d)?.ToDisplayString())
                .Where(n => n != null)!);

        var result = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in comp.SyntaxTrees.Skip(1))
        {
            SemanticModel model = comp.GetSemanticModel(tree);
            foreach (BaseTypeDeclarationSyntax decl in tree.GetRoot().DescendantNodes().OfType<BaseTypeDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(decl) is not INamedTypeSymbol sym)
                {
                    continue;
                }

                bool isResolver = sym.AllInterfaces.Any(i => i.Name == "IFormatterResolver");
                if (userTypes.Contains(sym.ToDisplayString()) && !isResolver)
                {
                    continue;
                }

                if (!result.Contains(sym, SymbolEqualityComparer.Default))
                {
                    result.Add(sym);
                }
            }
        }

        return result;
    }

    private static void AssertAllAnnotated(Compilation comp, string label)
    {
        List<INamedTypeSymbol> types = EmittedTypes(comp);
        Assert.NotEmpty(types);
        string[] missing = types.Where(t => !HasCoverageAttr(t)).Select(t => t.ToDisplayString()).ToArray();
        Assert.True(missing.Length == 0, $"[{label}] types missing [ExcludeFromCodeCoverage]: {string.Join(", ", missing)}");
    }

    // criterion: AC-1 — every formatter (object, string-key, enum, union, generic) and resolver the generator emits carries [ExcludeFromCodeCoverage].
    [Fact]
    public async Task C1_AC_1_AllEmittedTypesAnnotated_DefaultTarget()
    {
        (Compilation output, _) = await RunAsync(RichSource);
        Compilation comp = Reparse(output, new string[0]);
        List<INamedTypeSymbol> types = EmittedTypes(comp);

        string[] names = types.Select(t => t.Name).ToArray();
        Assert.Contains(names, n => n.Contains("Person"));
        Assert.Contains(names, n => n.Contains("Named"));
        Assert.Contains(names, n => n.Contains("Color"));
        Assert.Contains(names, n => n.Contains("IAnimal"));
        Assert.Contains(names, n => n.Contains("Box"));
        Assert.Contains(names, n => n == "MyResolver");

        AssertAllAnnotated(comp, "default");
    }

    // criterion: AC-1 — helper types nested inside a resolver (FormatterCache, GetFormatterHelper) and resolvers nested in user types are also annotated.
    [Fact]
    public async Task C2_AC_1_NestedResolverAndHelperTypesAnnotated()
    {
        string source = @"
using MessagePack;
namespace App
{
    [MessagePackObject] public class Item { [Key(0)] public int Id { get; set; } }
    [MessagePackObject] public class Holder { [Key(0)] public Item I { get; set; } }
    public partial class Host
    {
        [GeneratedMessagePackResolver] public partial class InnerResolver { public string Mine() => ""x""; }
    }
}";
        (Compilation output, _) = await RunAsync(source);
        Compilation comp = Reparse(output, new string[0]);
        List<INamedTypeSymbol> types = EmittedTypes(comp);

        Assert.Contains(types, t => t.Name == "InnerResolver");
        Assert.Contains(types, t => t.Name == "FormatterCache");
        Assert.Contains(types, t => t.Name.EndsWith("GetFormatterHelper"));
        AssertAllAnnotated(comp, "nested");
    }

    // criterion: AC-2 — on every target where the attribute exists (net8, net6, netcoreapp3.1, netstandard2.1) the generated types are annotated.
    [Fact]
    public async Task C3_AC_2_AnnotatedOnAllTargetsWhereAttributeExists()
    {
        (Compilation output, _) = await RunAsync(RichSource);
        foreach (string[] symbols in AttributeTargets)
        {
            Compilation comp = Reparse(output, symbols);
            AssertAllAnnotated(comp, string.Join("+", symbols));
        }
    }

    // criterion: AC-2 — targets without the attribute (netstandard2.0 / .NET Framework) still compile and user-declared types are not touched.
    [Fact]
    public async Task C4_AC_2_LegacyTargetsStillCompileWithoutAttributeOnUserTypes()
    {
        (Compilation output, _) = await RunAsync(RichSource);
        foreach (string[] symbols in LegacyTargets)
        {
            Compilation comp = Reparse(output, symbols);
            List<Diagnostic> errors = CompilerErrors(comp);
            Assert.True(errors.Count == 0, $"[{string.Join("+", symbols)}] {Describe(errors)}");

            SyntaxTree original = comp.SyntaxTrees.First();
            SemanticModel m = comp.GetSemanticModel(original);
            INamedTypeSymbol person = (INamedTypeSymbol)m.GetDeclaredSymbol(
                original.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>().First(c => c.Identifier.Text == "Person"))!;
            Assert.False(HasCoverageAttr(person));
        }
    }

    // criterion: AC-3 — a user whose partial resolver is already annotated with [ExcludeFromCodeCoverage] still compiles with no duplicate-attribute error.
    [Fact]
    public async Task C5_AC_3_UserResolverAlreadyAnnotated()
    {
        string source = @"
using System.Diagnostics.CodeAnalysis;
using MessagePack;
namespace App
{
    [MessagePackObject] public class Item { [Key(0)] public int Id { get; set; } }
    [ExcludeFromCodeCoverage]
    [GeneratedMessagePackResolver] public partial class MyResolver { public int UserMember => 1; }
}";
        (Compilation output, _) = await RunAsync(source);
        foreach (string[] symbols in AttributeTargets.Concat(LegacyTargets))
        {
            Compilation comp = Reparse(output, symbols);
            List<Diagnostic> errors = CompilerErrors(comp);
            Assert.True(errors.Count == 0, $"[{string.Join("+", symbols)}] {Describe(errors)}");
        }
    }

    // criterion: AC-3 — resolvers nested inside generic, constrained user containers still compile on every target.
    [Fact]
    public async Task C6_AC_3_NestedInGenericConstrainedContainerCompiles()
    {
        string source = @"
using MessagePack;
namespace App
{
    [MessagePackObject] public class Item { [Key(0)] public int Id { get; set; } }
    public partial class Host<T> where T : class
    {
        [GeneratedMessagePackResolver] public partial class InnerResolver { }
    }
    public partial class Plain
    {
        [GeneratedMessagePackResolver] public partial class OtherResolver { }
    }
}";
        (Compilation output, _) = await RunAsync(source);
        (_, ImmutableArray<Diagnostic> baseDiags) = (output, output.GetDiagnostics());
        // Only compare compile-level errors of the generated output across targets.
        foreach (string[] symbols in AttributeTargets.Concat(LegacyTargets))
        {
            Compilation comp = Reparse(output, symbols);
            List<Diagnostic> errors = CompilerErrors(comp);
            Assert.True(errors.Count == 0, $"[{string.Join("+", symbols)}] {Describe(errors)}");
        }
    }

    // criterion: AC-3 — a user project that declares its own System.* namespaces or look-alike attribute types is not broken by the emitted attribute.
    [Fact]
    public async Task C7_AC_3_UserShadowingNamespacesAndLookAlikeAttribute()
    {
        string source = @"
using MessagePack;
namespace App
{
    namespace System.Diagnostics.CodeAnalysis
    {
        public sealed class ExcludeFromCodeCoverageAttribute : global::System.Attribute { }
    }
    [MessagePackObject] public class Item { [Key(0)] public int Id { get; set; } }
    public enum Kind { A, B }
    [MessagePackObject] public class Holder { [Key(0)] public Kind K { get; set; } [Key(1)] public Item I { get; set; } }
    [GeneratedMessagePackResolver] public partial class MyResolver { }
}";
        (Compilation output, _) = await RunAsync(source);
        foreach (string[] symbols in AttributeTargets.Concat(LegacyTargets))
        {
            Compilation comp = Reparse(output, symbols);
            List<Diagnostic> errors = CompilerErrors(comp);
            Assert.True(errors.Count == 0, $"[{string.Join("+", symbols)}] {Describe(errors)}");
        }
    }

    // criterion: AC-4 — serialized bytes and round-trips (int keys, string keys, enum, union) are exactly the same as before the change.
    [Fact]
    public async Task C8_AC_4_SerializationBehaviourUnchanged()
    {
        string probe = @"
namespace App
{
    public static class Probe
    {
        private static readonly MessagePack.MessagePackSerializerOptions Opts =
            MessagePack.MessagePackSerializerOptions.Standard.WithResolver(
                MessagePack.Resolvers.CompositeResolver.Create(MyResolver.Instance, MessagePack.Resolvers.StandardResolver.Instance));

        public static byte[] PersonBytes() => MessagePack.MessagePackSerializer.Serialize(new Person { Name = ""ab"", Age = 7 }, Opts);
        public static bool PersonRoundTrips() { var p = MessagePack.MessagePackSerializer.Deserialize<Person>(PersonBytes(), Opts); return p.Name == ""ab"" && p.Age == 7; }
        public static byte[] PaintedBytes() => MessagePack.MessagePackSerializer.Serialize(new Painted { C = Color.Green }, Opts);
        public static bool PaintedRoundTrips() => MessagePack.MessagePackSerializer.Deserialize<Painted>(PaintedBytes(), Opts).C == Color.Green;
        public static bool NamedRoundTrips() { var b = MessagePack.MessagePackSerializer.Serialize(new Named { Title = ""t"", N = 5 }, Opts); var n = MessagePack.MessagePackSerializer.Deserialize<Named>(b, Opts); return n.Title == ""t"" && n.N == 5; }
        public static byte[] DogBytes() => MessagePack.MessagePackSerializer.Serialize<IAnimal>(new Dog { Name = ""d"" }, Opts);
        public static bool DogRoundTrips() => MessagePack.MessagePackSerializer.Deserialize<IAnimal>(DogBytes(), Opts) is Dog d && d.Name == ""d"";
        public static bool BoxRoundTrips() { var b = MessagePack.MessagePackSerializer.Serialize(new Box<int> { Value = 9 }, Opts); return MessagePack.MessagePackSerializer.Deserialize<Box<int>>(b, Opts).Value == 9; }
    }
}";
        // Append the probe to the rich source (inside its own namespace block).
        (Compilation output, _) = await RunAsync(RichSource + probe);

        using var ms = new MemoryStream();
        var emit = output.Emit(ms);
        Assert.True(emit.Success, Describe(emit.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));

        Assembly asm = Assembly.Load(ms.ToArray());
        Type probeType = asm.GetType("App.Probe")!;
        object? Call(string name) => probeType.GetMethod(name)!.Invoke(null, null);

        Assert.Equal(new byte[] { 0x92, 0xA2, 0x61, 0x62, 0x07 }, (byte[])Call("PersonBytes")!);
        Assert.Equal(new byte[] { 0x91, 0x01 }, (byte[])Call("PaintedBytes")!);
        Assert.Equal(new byte[] { 0x92, 0x00, 0x91, 0xA1, 0x64 }, (byte[])Call("DogBytes")!);
        Assert.True((bool)Call("PersonRoundTrips")!);
        Assert.True((bool)Call("PaintedRoundTrips")!);
        Assert.True((bool)Call("NamedRoundTrips")!);
        Assert.True((bool)Call("DogRoundTrips")!);
        Assert.True((bool)Call("BoxRoundTrips")!);
    }
}
